km <- function(t, e) {
  ut <- sort(unique(t)); S <- 1; v <- 0; out <- NULL
  for (u in ut) {
    n <- sum(t >= u); d <- sum(t == u & e == 1); c <- sum(t == u & e == 0)
    if (d > 0) { S <- S * (1 - d / n); v <- v + d / (n * (n - d)) }
    out <- rbind(out, data.frame(TIME = u, NRISK = n, NEVENT = d, NCENS = c, SURV = S, GW = v))
  }
  out
}
